	public static void RemoveMissionPeds()
	{
		if (MissionPeds1.Count > 0)
		{
			foreach (Ped item in MissionPeds1.ToList())
			{
				if (item != null)
				{
					if (item.AttachedBlip != null)
					{
						item.AttachedBlip.Delete();
					}
					item.Delete();
					MissionPeds1.Remove(item);
				}
			}
		}
		if (MissionPeds2.Count > 0)
		{
			foreach (Ped item2 in MissionPeds2.ToList())
			{
				if (item2 != null)
				{
					if (item2.AttachedBlip != null)
					{
						item2.AttachedBlip.Delete();
					}
					item2.Delete();
					MissionPeds2.Remove(item2);
				}
			}
		}
		if (MissionPeds3.Count > 0)
		{
			foreach (Ped item3 in MissionPeds3.ToList())
			{
				if (item3 != null)
				{
					if (item3.AttachedBlip != null)
					{
						item3.AttachedBlip.Delete();
					}
					item3.Delete();
					MissionPeds3.Remove(item3);
				}
			}
		}
		if (MissionPeds4.Count <= 0)
		{
			return;
		}
		foreach (Ped item4 in MissionPeds4.ToList())
		{
			if (item4 != null)
			{
				if (item4.AttachedBlip != null)
				{
					item4.AttachedBlip.Delete();
				}
				item4.Delete();
				MissionPeds4.Remove(item4);
			}
		}
	}

	public static void CheckMissionPeds()
	{
		if (MissionPeds1.Count > 0)
		{
			foreach (Ped item in MissionPeds1.ToList())
			{
				if (item != null && item.IsDead)
				{
					if (item.AttachedBlip != null)
					{
						item.AttachedBlip.Delete();
					}
					item.MarkAsNoLongerNeeded();
					MissionPeds1.Remove(item);
				}
			}
		}
		if (MissionPeds2.Count > 0)
		{
			foreach (Ped item2 in MissionPeds2.ToList())
			{
				if (item2 != null && item2.IsDead)
				{
					if (item2.AttachedBlip != null)
					{
						item2.AttachedBlip.Delete();
					}
					item2.MarkAsNoLongerNeeded();
					MissionPeds2.Remove(item2);
				}
			}
		}
		if (MissionPeds3.Count > 0)
		{
			foreach (Ped item3 in MissionPeds3.ToList())
			{
				if (item3 != null && item3.IsDead)
				{
					if (item3.AttachedBlip != null)
					{
						item3.AttachedBlip.Delete();
					}
					item3.MarkAsNoLongerNeeded();
					MissionPeds3.Remove(item3);
				}
			}
		}
		if (MissionPeds4.Count <= 0)
		{
			return;
		}
		foreach (Ped item4 in MissionPeds4.ToList())
		{
			if (item4 != null && item4.IsDead)
			{
				if (item4.AttachedBlip != null)
				{
					item4.AttachedBlip.Delete();
				}
				item4.MarkAsNoLongerNeeded();
				MissionPeds4.Remove(item4);
			}
		}
	}

	public static void AI_FRIENDS_ATTACK()
	{
		for (int i = 0; i < GroupIDs.Length; i++)
		{
			if (GroupIDs[i] != null && Groups.IS_PED_IN_GROUP(GroupIDs[i], Game.Player.Character.PedGroup.Handle))
			{
				GroupIDs[i].BlockPermanentEvents = true;
				GroupIDs[i].AlwaysKeepTask = true;
				GroupIDs[i].NeverLeavesGroup = false;
				Function.Call(Hash.SET_PED_COMBAT_ABILITY, GroupIDs[i], 2);
				Function.Call(Hash.SET_PED_COMBAT_MOVEMENT, GroupIDs[i], 2);
				Function.Call(Hash.SET_PED_COMBAT_ATTRIBUTES, GroupIDs[i], 0, true);
				Function.Call(Hash.SET_PED_COMBAT_ATTRIBUTES, GroupIDs[i], 1, true);
				Function.Call(Hash.SET_PED_COMBAT_ATTRIBUTES, GroupIDs[i], 2, true);
				Function.Call(Hash.SET_PED_COMBAT_ATTRIBUTES, GroupIDs[i], 3, true);
				Function.Call(Hash.SET_PED_COMBAT_ATTRIBUTES, GroupIDs[i], 12, true);
				Function.Call(Hash.SET_PED_COMBAT_ATTRIBUTES, GroupIDs[i], 38, true);
				Function.Call(Hash.SET_PED_COMBAT_ATTRIBUTES, GroupIDs[i], 41, true);
				Function.Call(Hash.SET_PED_COMBAT_ATTRIBUTES, GroupIDs[i], 42, true);
				Function.Call(Hash.SET_PED_COMBAT_ATTRIBUTES, GroupIDs[i], 43, true);
				Function.Call(Hash.SET_PED_COMBAT_ATTRIBUTES, GroupIDs[i], 44, false);
				Function.Call(Hash.SET_PED_COMBAT_ATTRIBUTES, GroupIDs[i], 54, true);
				Function.Call(Hash.SET_PED_COMBAT_ATTRIBUTES, GroupIDs[i], 60, true);
				Function.Call(Hash.SET_PED_COMBAT_ATTRIBUTES, GroupIDs[i], 24, true);
				GroupIDs[i].Accuracy = 75;
				GroupIDs[i].LeaveGroup();
				GroupIDs[i].Task.FightAgainstHatedTargets(500f, -1);
			}
		}
	}

	public static void AI_FRIENDS_REGROUP()
	{
		for (int i = 0; i < GroupIDs.Length; i++)
		{
			if (GroupIDs[i] != null && !Groups.IS_PED_IN_GROUP(GroupIDs[i], Game.Player.Character.PedGroup.Handle))
			{
				GroupIDs[i].BlockPermanentEvents = false;
				GroupIDs[i].AlwaysKeepTask = false;
				GroupIDs[i].NeverLeavesGroup = true;
				GroupIDs[i].Task.ClearAll();
				Groups.SET_INTO_GROUP(GroupIDs[i]);
			}
		}
	}

	public static bool THIS_PLAYER_NOTIF(Ped pedthatwaskilled = null, string msg = "", bool blinking = true)
	{
		if (pedthatwaskilled != null)
		{
			Entity killer = pedthatwaskilled.Killer;
			if (killer is Ped && killer as Ped == Game.Player.Character)
			{
				Notification.Show("~b~" + CruelMastersOnlineOffline.Player_Name + "~w~" + msg, blinking);
				return true;
			}
			if (killer is Ped && killer as Ped != Game.Player.Character && killer.AttachedBlip != null)
			{
				Notification.Show("~b~" + killer.AttachedBlip.Name + "~w~" + msg, blinking);
				return true;
			}
		}
		return false;
	}

	public static void DISPLAY_VEHICLE_HEALTH(float barx, float bary, float barwidth, float barheight, float healthpercent, float maxhealthpercent)
	{
		barX = barx;
		barY = bary;
		barWidth = barwidth;
		barHeight = barheight;
		float val = healthpercent / maxhealthpercent;
		float num = barWidth * Math.Min(val, 1f);
		float num2 = barX + num / 2f;
		Heist_Hud.drawSprite2("timerbars", "damagebarfill_128", barX, barY, barWidth, barHeight, 110, 110, 110, 255);
		Heist_Hud.drawSprite2("timerbars", "damagebarfill_128", num2 - 0.0395f, barY, num, barHeight, 255, 255, 255, 255);
	}

	public static void PLAY_SAFE_CRACK_SOUND_WITH_ID(int Sound, int SoundID, float SoundVariable = 0f)
	{
		switch (Sound)
		{
		case 0:
			if (SoundID == -1)
			{
				SoundID = Function.Call<int>(Hash.GET_SOUND_ID);
				break;
			}
			Function.Call(Hash.STOP_SOUND, SoundID);
			Function.Call(Hash.RELEASE_SOUND_ID, SoundID);
			SoundID = Function.Call<int>(Hash.GET_SOUND_ID);
			break;
		case 1:
			if (SoundID == -1)
			{
				SoundID = Function.Call<int>(Hash.GET_SOUND_ID);
			}
			else
			{
				Function.Call(Hash.STOP_SOUND, SoundID);
				Function.Call(Hash.RELEASE_SOUND_ID, SoundID);
				SoundID = Function.Call<int>(Hash.GET_SOUND_ID);
			}
			Function.Call(Hash.PLAY_SOUND_FRONTEND, SoundID, "TUMBLER_RESET", "SAFE_CRACK_SOUNDSET", true);
			break;
		case 2:
			if (SoundID == -1)
			{
				SoundID = Function.Call<int>(Hash.GET_SOUND_ID);
			}
			else
			{
				Function.Call(Hash.STOP_SOUND, SoundID);
				Function.Call(Hash.RELEASE_SOUND_ID, SoundID);
				SoundID = Function.Call<int>(Hash.GET_SOUND_ID);
			}
			Function.Call(Hash.PLAY_SOUND_FRONTEND, SoundID, "TUMBLER_PIN_FALL", "SAFE_CRACK_SOUNDSET", true);
			break;
		case 3:
			if (SoundID == -1)
			{
				SoundID = Function.Call<int>(Hash.GET_SOUND_ID);
			}
			else
			{
				Function.Call(Hash.STOP_SOUND, SoundID);
				Function.Call(Hash.RELEASE_SOUND_ID, SoundID);
				SoundID = Function.Call<int>(Hash.GET_SOUND_ID);
			}
			Function.Call(Hash.PLAY_SOUND_FRONTEND, SoundID, "TUMBLER_PIN_FALL_FINAL", "SAFE_CRACK_SOUNDSET", true);
			break;
		case 4:
			if (SoundID == -1)
			{
				SoundID = Function.Call<int>(Hash.GET_SOUND_ID);
			}
			else
			{
				Function.Call(Hash.STOP_SOUND, SoundID);
				Function.Call(Hash.RELEASE_SOUND_ID, SoundID);
				SoundID = Function.Call<int>(Hash.GET_SOUND_ID);
			}
			Function.Call(Hash.PLAY_SOUND_FRONTEND, SoundID, "SAFE_DOOR_OPEN", "SAFE_CRACK_SOUNDSET", true);
			break;
		case 5:
			if (SoundID == -1)
			{
				SoundID = Function.Call<int>(Hash.GET_SOUND_ID);
			}
			else
			{
				Function.Call(Hash.STOP_SOUND, SoundID);
				Function.Call(Hash.RELEASE_SOUND_ID, SoundID);
				SoundID = Function.Call<int>(Hash.GET_SOUND_ID);
			}
			Function.Call(Hash.PLAY_SOUND_FRONTEND, SoundID, "SAFE_DOOR_CLOSE", "SAFE_CRACK_SOUNDSET", true);
			break;
		}
