	public void onShutdown(object sender, EventArgs e)
	{
		if (GeraldBlip != null)
		{
			GeraldBlip.Delete();
		}
		if (CarryPed != null)
		{
			CarryPed.Delete();
		}
		Function.Call(Hash.WATER_OVERRIDE_SET_STRENGTH, 0f);
		for (int i = 0; i < SalvaHenchmen.Length; i++)
		{
			if (SalvaHenchmen[i] != null)
			{
				if (SalvaHenchmen[i].AttachedBlip != null)
				{
					SalvaHenchmen[i].AttachedBlip.Delete();
				}
				SalvaHenchmen[i].Delete();
			}
		}
		for (int j = 0; j < MissionProps.Length; j++)
		{
			if (MissionProps[j] != null)
			{
				if (MissionProps[j].AttachedBlip != null)
				{
					MissionProps[j].AttachedBlip.Delete();
				}
				MissionProps[j].Delete();
			}
		}
		for (int k = 0; k < MissionVehs.Length; k++)
		{
			if (MissionVehs[k] != null)
			{
				if (MissionVehs[k].AttachedBlip != null)
				{
					MissionVehs[k].AttachedBlip.Delete();
				}
				MissionVehs[k].Delete();
			}
		}
		for (int l = 0; l < MissionBlips.Length; l++)
		{
			if (MissionBlips[l] != null)
			{
				MissionBlips[l].Delete();
			}
		}
		for (int m = 0; m < MissionPickups.Length; m++)
		{
			if (MissionPickups[m] != null)
			{
				MissionPickups[m].Delete();
			}
		}
		RemoveMissionPeds();
		CLEAR_ALL_SAFE_CRACK_TASK_SEQS();
		Audio.StopSound(SoundID);
		Audio.ReleaseSound(SoundID);
	}
}
